-- Apply Phase 2 to an existing easner-website project (generated by supabase/build-apply-phase2.mjs; do not edit).
-- Run once in the Supabase SQL editor, after the earlier setup. It is one transaction: it applies fully or not at all.
-- Contains: 20261115120000_blog_review_workflow.sql, 20261115130000_member_author_profiles.sql

begin;

-- >>> 20261115120000_blog_review_workflow.sql
-- Phase 2: the review workflow (docs/blog-and-admin-plan.md §8 decision 2).
--
--   * Writer submits, Editor approves or requests changes (with comments), Editor publishes.
--   * A claims check (fees, rates, FX margins, yields, "insured"/FDIC, regulatory statements, competitor comparisons)
--     flags a post inside the database. A flagged post needs a second Editor: the author never publishes it, and at
--     least two different editors must stand behind the current version. Any edit voids earlier approvals.
--   * Status only changes through the functions below. Direct writes to `status` are refused for every role.
--   * Slugs lock after first publish (owners only afterwards). `summary` becomes a published field.
--   * New: comments, approvals, claim patterns, archive, ensure_my_author, blog_media_usage.

-- ---------------------------------------------------------------------------------------------------------------
-- Claim patterns (the single list; admin/lib/blog/claims-patterns.json carries the same rows and a test keeps them equal)
-- ---------------------------------------------------------------------------------------------------------------

create table public.blog_claim_patterns (
  id text primary key,
  category text not null,
  label text not null,
  -- A JS regex source, matched case-insensitively. `\b` is turned into Postgres' `\y` when it runs here.
  pattern text not null,
  created_at timestamptz not null default now()
);

alter table public.blog_claim_patterns enable row level security;
create policy "Members read claim patterns" on public.blog_claim_patterns
  for select to authenticated using (public.is_admin_member());
revoke all on public.blog_claim_patterns from anon;
revoke insert, update, delete, truncate on public.blog_claim_patterns from authenticated;

insert into public.blog_claim_patterns (id, category, label, pattern) values
  ('fees-amount', 'fees', 'A fee amount', $re$\b(?:fees?|charges?|costs?)\b[^.\n]{0,40}\b(?:\d+(?:\.\d+)?\s?%|[$€£]\s?\d+)$re$),
  ('fees-none', 'fees', 'No or low fees', $re$\b(?:no|zero|low|lowest|cheapest|hidden)[- ](?:fees?|charges?|costs?)\b$re$),
  ('fees-free', 'fees', 'Free transfers or accounts', $re$\bfree (?:transfers?|payments?|payouts?|accounts?|conversions?|withdrawals?)\b$re$),
  ('rates-apy', 'rates', 'Interest rate or APY', $re$\b(?:apy|apr|interest rates?|interest of)\b$re$),
  ('rates-earn', 'rates', 'Earning a return', $re$\b(?:earn|earns|earning)\b[^.\n]{0,30}\b(?:\d+(?:\.\d+)?\s?%|interest|yield|returns?)\b$re$),
  ('yield', 'yields', 'Yield or returns', $re$\b(?:yields?|guaranteed returns?|returns? of \d)\b$re$),
  ('fx-margin', 'fx', 'FX margin or spread', $re$\b(?:fx|exchange|forex|currency)[ -](?:margins?|spreads?|markups?|rates? (?:of|at))\b$re$),
  ('fx-mid-market', 'fx', 'Mid-market rate claim', $re$\b(?:mid-market|interbank|real) (?:exchange )?rates?\b$re$),
  ('insured', 'insured', 'Insured or protected deposits', $re$\b(?:fdic|insured|deposit insurance|deposit protection|protected deposits?|ncua)\b$re$),
  ('bank-claim', 'insured', 'Claims Easner is a bank', $re$\beasner is (?:a )?bank\b$re$),
  ('licensed', 'regulatory', 'Licensing statement', $re$\b(?:licensed|licensing|licen[cs]es? (?:in|from|to)|authori[sz]ed by)\b$re$),
  ('regulated', 'regulatory', 'Regulatory statement', $re$\b(?:regulated (?:by|in|as)|regulator|compliant with|compliance with|fully compliant|gdpr|aml|kyc|sanctions)\b$re$),
  ('competitor-name', 'competitors', 'Names a competitor', $re$\b(?:wise|transferwise|remitly|western union|moneygram|paypal|revolut|payoneer|worldremit|stripe|airwallex|monzo|wells fargo|bank of america)\b$re$),
  ('competitor-compare', 'competitors', 'Compares with banks or rivals', $re$\b(?:cheaper than|faster than|better than|lower than|vs|versus|compared (?:to|with)|unlike (?:banks|wise|paypal))\b$re$);

-- ---------------------------------------------------------------------------------------------------------------
-- Post columns
-- ---------------------------------------------------------------------------------------------------------------

alter table public.blog_posts
  add column claims_flagged boolean not null default false,
  add column claims_matches text[] not null default '{}';

comment on column public.blog_posts.claims_flagged is 'Set by trigger from blog_claim_patterns. A flagged post needs a second editor.';

-- Ids of the claim patterns found in a piece of text.
create function public.blog_claims_scan(p_text text)
returns text[]
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(array_agg(c.id order by c.id), '{}'::text[])
  from public.blog_claim_patterns c
  where p_text ~* replace(c.pattern, '\b', '\y')
$$;

-- Recomputes the flag whenever the words change. Clients can't set it: whatever they send is overwritten.
create function public.blog_posts_claims()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  scan text;
begin
  if tg_op = 'UPDATE'
     and new.title is not distinct from old.title
     and new.excerpt is not distinct from old.excerpt
     and new.draft_content is not distinct from old.draft_content
     and new.content is not distinct from old.content then
    new.claims_flagged := old.claims_flagged;
    new.claims_matches := old.claims_matches;
    return new;
  end if;
  scan := coalesce(new.title, '') || E'\n' || coalesce(new.excerpt, '') || E'\n'
          || public.blog_doc_text(coalesce(new.draft_content, new.content));
  new.claims_matches := public.blog_claims_scan(scan);
  new.claims_flagged := cardinality(new.claims_matches) > 0;
  return new;
end
$$;

create trigger blog_posts_claims before insert or update on public.blog_posts
  for each row execute function public.blog_posts_claims();

-- ---------------------------------------------------------------------------------------------------------------
-- Guard: status moves only through the functions; slug locks after first publish; summary is a published field
-- ---------------------------------------------------------------------------------------------------------------

create or replace function public.blog_posts_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  new.updated_by := coalesce(auth.uid(), new.updated_by);

  -- Server jobs (service role, no user) and the trusted functions write freely.
  if public.blog_in_trusted_write() or auth.uid() is null then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.created_by is distinct from auth.uid() then
      raise exception 'A post is created by the person signed in.' using errcode = 'insufficient_privilege';
    end if;
    if new.status <> 'draft' then
      raise exception 'New posts start as drafts. Use submit_for_review() and publish_post().' using errcode = 'insufficient_privilege';
    end if;
    if new.content is not null or new.content_text is not null or new.published_at is not null
       or new.content_modified_at is not null or new.summary is not null then
      raise exception 'Published fields are set by publish_post().' using errcode = 'insufficient_privilege';
    end if;
    new.word_count := 0;
    new.reading_minutes := 0;
  else
    if new.created_by is distinct from old.created_by or new.created_at is distinct from old.created_at then
      raise exception 'A post''s creator can''t change.' using errcode = 'insufficient_privilege';
    end if;
    if new.status is distinct from old.status then
      raise exception 'The status changes through submit_for_review(), request_changes(), publish_post(), unpublish_post() and archive_post().'
        using errcode = 'insufficient_privilege';
    end if;
    if new.content is distinct from old.content
       or new.content_text is distinct from old.content_text
       or new.summary is distinct from old.summary
       or new.published_at is distinct from old.published_at
       or new.content_modified_at is distinct from old.content_modified_at
       or new.word_count is distinct from old.word_count
       or new.reading_minutes is distinct from old.reading_minutes then
      raise exception 'Published fields are set by publish_post().' using errcode = 'insufficient_privilege';
    end if;
    -- A published post's URL is part of what the web has linked to: only an owner changes it afterwards.
    if new.slug is distinct from old.slug and old.published_at is not null and not public.is_admin_owner() then
      raise exception 'This post has been published, so only an owner can change its URL.' using errcode = 'insufficient_privilege';
    end if;
  end if;

  if not public.is_blog_editor() then
    if (tg_op = 'INSERT' and (new.featured or new.featured_rank is not null))
       or (tg_op = 'UPDATE' and (new.featured is distinct from old.featured
                                 or new.featured_rank is distinct from old.featured_rank)) then
      raise exception 'Only an editor can feature a post.' using errcode = 'insufficient_privilege';
    end if;
  end if;

  return new;
end
$$;

-- ---------------------------------------------------------------------------------------------------------------
-- Comments and approvals
-- ---------------------------------------------------------------------------------------------------------------

create table public.blog_post_comments (
  id uuid primary key default gen_random_uuid(),
  post_id uuid not null references public.blog_posts (id) on delete cascade,
  parent_id uuid references public.blog_post_comments (id) on delete cascade,
  author_id uuid default auth.uid() references public.admin_members (user_id) on delete set null,
  body text not null check (char_length(body) between 1 and 2000),
  -- The highlighted text the comment is anchored to.
  quote text check (char_length(quote) <= 500),
  kind text not null default 'comment' check (kind in ('comment', 'change_request', 'brand')),
  resolved_at timestamptz,
  resolved_by uuid references public.admin_members (user_id) on delete set null,
  created_at timestamptz not null default now()
);

create index blog_post_comments_post_idx on public.blog_post_comments (post_id, created_at);

create table public.blog_post_approvals (
  id uuid primary key default gen_random_uuid(),
  post_id uuid not null references public.blog_posts (id) on delete cascade,
  approver uuid not null references public.admin_members (user_id) on delete cascade,
  -- blog_post_version_hash() at the time. An approval counts only while this equals the current hash.
  version_hash text not null,
  created_at timestamptz not null default now(),
  unique (post_id, approver, version_hash)
);

create index blog_post_approvals_post_idx on public.blog_post_approvals (post_id);

alter table public.blog_post_comments enable row level security;
alter table public.blog_post_approvals enable row level security;

create policy "Members read comments" on public.blog_post_comments
  for select to authenticated using (public.is_admin_member());
create policy "Editors and the creator comment" on public.blog_post_comments
  for insert to authenticated
  with check (
    author_id = auth.uid()
    and (
      public.is_blog_editor()
      or (
        public.is_admin_member()
        and exists (select 1 from public.blog_posts p where p.id = post_id and p.created_by = auth.uid())
      )
    )
  );
create policy "Editors and the creator resolve comments" on public.blog_post_comments
  for update to authenticated
  using (
    public.is_blog_editor()
    or (public.is_admin_member() and exists (select 1 from public.blog_posts p where p.id = post_id and p.created_by = auth.uid()))
  )
  with check (
    public.is_blog_editor()
    or (public.is_admin_member() and exists (select 1 from public.blog_posts p where p.id = post_id and p.created_by = auth.uid()))
  );
create policy "Authors and editors delete comments" on public.blog_post_comments
  for delete to authenticated
  using (public.is_blog_editor() or (public.is_admin_member() and author_id = auth.uid()));

create policy "Members read approvals" on public.blog_post_approvals
  for select to authenticated using (public.is_admin_member());

revoke all on public.blog_post_comments, public.blog_post_approvals from anon;
-- Comments: only resolving can be edited. Approvals: written by approve_post() / publish_post() only.
revoke update on public.blog_post_comments from authenticated;
grant update (resolved_at, resolved_by) on public.blog_post_comments to authenticated;
revoke insert, update, delete, truncate on public.blog_post_approvals from authenticated;

-- ---------------------------------------------------------------------------------------------------------------
-- Version hash and review state
-- ---------------------------------------------------------------------------------------------------------------

create function public.blog_post_version_hash(p_post_id uuid)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select case when public.is_admin_member() then
    (select md5(coalesce(p.title, '') || '|' || coalesce(p.excerpt, '') || '|' || coalesce(coalesce(p.draft_content, p.content)::text, ''))
     from public.blog_posts p where p.id = p_post_id)
  end
$$;

-- Editors/owners who stand behind the current version: current-hash approvers, plus the creator when they are one.
create function public.blog_approving_editors(p_post_id uuid)
returns uuid[]
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(array_agg(distinct u), '{}'::uuid[])
  from (
    select a.approver as u
    from public.blog_post_approvals a
    join public.admin_members m on m.user_id = a.approver and m.role in ('owner', 'editor')
    where a.post_id = p_post_id and a.version_hash = public.blog_post_version_hash(p_post_id)
    union
    select p.created_by
    from public.blog_posts p
    join public.admin_members m on m.user_id = p.created_by and m.role in ('owner', 'editor')
    where p.id = p_post_id
  ) s
$$;

create function public.blog_post_review_state(p_post_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  post public.blog_posts;
  hash text;
  editors uuid[];
  creator_editor boolean;
begin
  if not public.is_admin_member() then
    raise exception 'Not allowed.' using errcode = 'insufficient_privilege';
  end if;
  select * into post from public.blog_posts where id = p_post_id;
  if not found then
    raise exception 'Post not found.' using errcode = 'no_data_found';
  end if;
  hash := public.blog_post_version_hash(p_post_id);
  editors := public.blog_approving_editors(p_post_id);
  creator_editor := exists (
    select 1 from public.admin_members m where m.user_id = post.created_by and m.role in ('owner', 'editor'));
  return jsonb_build_object(
    'flagged', post.claims_flagged,
    'matches', to_jsonb(post.claims_matches),
    'version_hash', hash,
    'creator', post.created_by,
    'creator_is_editor', creator_editor,
    'approvals', coalesce((
      select jsonb_agg(jsonb_build_object('approver', a.approver, 'name', m.name, 'at', a.created_at) order by a.created_at)
      from public.blog_post_approvals a
      join public.admin_members m on m.user_id = a.approver
      where a.post_id = p_post_id and a.version_hash = hash
    ), '[]'::jsonb),
    'needed', case when post.claims_flagged then 2 else 0 end,
    'have', cardinality(editors) - case when auth.uid() = any (editors) then 1 else 0 end
  );
end
$$;

-- ---------------------------------------------------------------------------------------------------------------
-- Workflow functions
-- ---------------------------------------------------------------------------------------------------------------

create function public.submit_for_review(p_post_id uuid)
returns public.blog_posts
language plpgsql
security definer
set search_path = ''
as $$
declare
  post public.blog_posts;
begin
  if not public.is_admin_member() then
    raise exception 'Not allowed.' using errcode = 'insufficient_privilege';
  end if;
  select * into post from public.blog_posts where id = p_post_id for update;
  if not found then
    raise exception 'Post not found.' using errcode = 'no_data_found';
  end if;
  if not (public.is_blog_editor() or post.created_by = auth.uid()) then
    raise exception 'You can only submit your own posts.' using errcode = 'insufficient_privilege';
  end if;
  if post.status not in ('draft', 'changes_requested') then
    raise exception 'This post can''t be submitted from its current status.' using errcode = 'check_violation';
  end if;
  if char_length(btrim(post.title)) = 0 or coalesce(post.draft_content, post.content) is null then
    raise exception 'Add a title and some content before submitting.' using errcode = 'check_violation';
  end if;

  perform set_config('easner.blog_trusted_write', 'on', true);
  update public.blog_posts p set status = 'in_review' where p.id = p_post_id returning * into post;
  perform set_config('easner.blog_trusted_write', 'off', true);

  perform public.log_admin_activity('post.submitted', 'blog_post', post.id::text, jsonb_build_object('slug', post.slug));
  return post;
end
$$;

create function public.withdraw_submission(p_post_id uuid)
returns public.blog_posts
language plpgsql
security definer
set search_path = ''
as $$
declare
  post public.blog_posts;
begin
  if not public.is_admin_member() then
    raise exception 'Not allowed.' using errcode = 'insufficient_privilege';
  end if;
  select * into post from public.blog_posts where id = p_post_id for update;
  if not found then
    raise exception 'Post not found.' using errcode = 'no_data_found';
  end if;
  if not (public.is_blog_editor() or post.created_by = auth.uid()) then
    raise exception 'You can only withdraw your own posts.' using errcode = 'insufficient_privilege';
  end if;
  if post.status <> 'in_review' then
    raise exception 'This post isn''t in review.' using errcode = 'check_violation';
  end if;

  perform set_config('easner.blog_trusted_write', 'on', true);
  update public.blog_posts p set status = 'draft' where p.id = p_post_id returning * into post;
  perform set_config('easner.blog_trusted_write', 'off', true);

  perform public.log_admin_activity('post.withdrawn', 'blog_post', post.id::text, jsonb_build_object('slug', post.slug));
  return post;
end
$$;

create function public.request_changes(p_post_id uuid, p_comment text default null)
returns public.blog_posts
language plpgsql
security definer
set search_path = ''
as $$
declare
  post public.blog_posts;
begin
  if not public.is_blog_editor() then
    raise exception 'Only an editor can request changes.' using errcode = 'insufficient_privilege';
  end if;
  select * into post from public.blog_posts where id = p_post_id for update;
  if not found then
    raise exception 'Post not found.' using errcode = 'no_data_found';
  end if;
  if post.status <> 'in_review' then
    raise exception 'This post isn''t in review.' using errcode = 'check_violation';
  end if;

  perform set_config('easner.blog_trusted_write', 'on', true);
  update public.blog_posts p set status = 'changes_requested' where p.id = p_post_id returning * into post;
  perform set_config('easner.blog_trusted_write', 'off', true);

  if p_comment is not null and char_length(btrim(p_comment)) > 0 then
    insert into public.blog_post_comments (post_id, author_id, body, kind)
    values (post.id, auth.uid(), left(btrim(p_comment), 2000), 'change_request');
  end if;
  perform public.log_admin_activity('post.changes_requested', 'blog_post', post.id::text, jsonb_build_object('slug', post.slug));
  return post;
end
$$;

-- Records the caller's approval of the current version. It does not publish. The post's creator never approves it.
create function public.approve_post(p_post_id uuid)
returns public.blog_posts
language plpgsql
security definer
set search_path = ''
as $$
declare
  post public.blog_posts;
begin
  if not public.is_blog_editor() then
    raise exception 'Only an editor can approve a post.' using errcode = 'insufficient_privilege';
  end if;
  select * into post from public.blog_posts where id = p_post_id for update;
  if not found then
    raise exception 'Post not found.' using errcode = 'no_data_found';
  end if;
  if post.created_by = auth.uid() then
    raise exception 'You can''t approve your own post. Another editor has to.' using errcode = 'insufficient_privilege';
  end if;
  if not (post.status = 'in_review' or (post.status = 'published' and post.draft_content is not null)) then
    raise exception 'Only a post in review, or a live post with changes, can be approved.' using errcode = 'check_violation';
  end if;

  insert into public.blog_post_approvals (post_id, approver, version_hash)
  values (post.id, auth.uid(), public.blog_post_version_hash(post.id))
  on conflict do nothing;

  perform public.log_admin_activity('post.approved', 'blog_post', post.id::text, jsonb_build_object('slug', post.slug));
  return post;
end
$$;

drop function public.publish_post(uuid, boolean);

create function public.publish_post(
  p_post_id uuid,
  p_significant_update boolean default true,
  p_content_text text default null,
  p_word_count integer default null,
  p_reading_minutes integer default null,
  p_summary text default null
)
returns public.blog_posts
language plpgsql
security definer
set search_path = ''
as $$
declare
  post public.blog_posts;
  doc jsonb;
  doc_text text;
  words integer;
  first_publish boolean;
  approvers uuid[];
begin
  if not public.is_blog_editor() then
    raise exception 'Only an editor or owner can publish.' using errcode = 'insufficient_privilege';
  end if;

  select * into post from public.blog_posts where id = p_post_id for update;
  if not found then
    raise exception 'Post not found.' using errcode = 'no_data_found';
  end if;
  if post.status = 'archived' then
    raise exception 'Restore an archived post before publishing it.' using errcode = 'check_violation';
  end if;

  doc := coalesce(post.draft_content, post.content);
  if doc is null then
    raise exception 'This post has no content yet.' using errcode = 'check_violation';
  end if;
  if char_length(btrim(post.title)) = 0 then
    raise exception 'Add a title before publishing.' using errcode = 'check_violation';
  end if;
  if post.category_id is null then
    raise exception 'Choose a category before publishing.' using errcode = 'check_violation';
  end if;
  if post.cover_path is null or char_length(btrim(coalesce(post.cover_alt, ''))) = 0 then
    raise exception 'Add a cover image with alt text before publishing.' using errcode = 'check_violation';
  end if;

  -- Claims: the creator never publishes a flagged post, and two different editors have to stand behind it.
  if post.claims_flagged then
    if post.created_by = auth.uid() then
      raise exception 'This post makes claims that need a second editor (fees, rates, insurance, regulation or comparisons). Its author can''t publish it.'
        using errcode = 'check_violation';
    end if;
    approvers := public.blog_approving_editors(post.id);
    if not (auth.uid() = any (approvers)) then
      approvers := approvers || auth.uid();
    end if;
    if cardinality(approvers) < 2 then
      raise exception 'This post makes claims about fees, rates, insurance, regulation or competitors. A second Editor has to approve it.'
        using errcode = 'check_violation';
    end if;
  end if;

  doc_text := public.blog_doc_text(doc);
  words := coalesce(array_length(regexp_split_to_array(btrim(doc_text), '\s+'), 1), 0);
  if btrim(doc_text) = '' then
    words := 0;
  end if;
  first_publish := post.published_at is null;

  -- The publisher's own approval, for the current version (the hash is the same before and after the swap).
  insert into public.blog_post_approvals (post_id, approver, version_hash)
  values (post.id, auth.uid(), public.blog_post_version_hash(post.id))
  on conflict do nothing;

  perform set_config('easner.blog_trusted_write', 'on', true);
  update public.blog_posts p set
    content = doc,
    draft_content = null,
    content_text = coalesce(p_content_text, doc_text),
    summary = p_summary,
    word_count = coalesce(p_word_count, words),
    reading_minutes = coalesce(p_reading_minutes, greatest(1, ceil(words / 230.0)::integer)),
    status = 'published',
    published_at = coalesce(p.published_at, now()),
    scheduled_for = null,
    content_modified_at = case
      when first_publish or p_significant_update then now()
      else p.content_modified_at
    end
  where p.id = p_post_id
  returning * into post;
  perform set_config('easner.blog_trusted_write', 'off', true);

  insert into public.blog_revisions (post_id, content, title, excerpt, kind)
  values (post.id, post.content, post.title, post.excerpt, 'publish');

  perform public.log_admin_activity(
    case when first_publish then 'post.published' else 'post.updated' end,
    'blog_post', post.id::text,
    jsonb_build_object('slug', post.slug, 'significant', p_significant_update));

  return post;
end
$$;

create function public.archive_post(p_post_id uuid)
returns public.blog_posts
language plpgsql
security definer
set search_path = ''
as $$
declare
  post public.blog_posts;
begin
  if not public.is_blog_editor() then
    raise exception 'Only an editor or owner can archive.' using errcode = 'insufficient_privilege';
  end if;
  select * into post from public.blog_posts where id = p_post_id for update;
  if not found then
    raise exception 'Post not found.' using errcode = 'no_data_found';
  end if;
  if post.status = 'archived' then
    raise exception 'This post is already archived.' using errcode = 'check_violation';
  end if;

  perform set_config('easner.blog_trusted_write', 'on', true);
  update public.blog_posts p set status = 'archived', scheduled_for = null where p.id = p_post_id returning * into post;
  perform set_config('easner.blog_trusted_write', 'off', true);

  perform public.log_admin_activity('post.archived', 'blog_post', post.id::text, jsonb_build_object('slug', post.slug));
  return post;
end
$$;

create function public.unarchive_post(p_post_id uuid)
returns public.blog_posts
language plpgsql
security definer
set search_path = ''
as $$
declare
  post public.blog_posts;
begin
  if not public.is_blog_editor() then
    raise exception 'Only an editor or owner can restore a post.' using errcode = 'insufficient_privilege';
  end if;
  select * into post from public.blog_posts where id = p_post_id for update;
  if not found then
    raise exception 'Post not found.' using errcode = 'no_data_found';
  end if;
  if post.status <> 'archived' then
    raise exception 'This post isn''t archived.' using errcode = 'check_violation';
  end if;

  perform set_config('easner.blog_trusted_write', 'on', true);
  update public.blog_posts p set
    status = 'draft',
    draft_content = coalesce(p.draft_content, p.content)
  where p.id = p_post_id returning * into post;
  perform set_config('easner.blog_trusted_write', 'off', true);

  perform public.log_admin_activity('post.unarchived', 'blog_post', post.id::text, jsonb_build_object('slug', post.slug));
  return post;
end
$$;

-- ---------------------------------------------------------------------------------------------------------------
-- My profile and media usage
-- ---------------------------------------------------------------------------------------------------------------

create function public.ensure_my_author()
returns public.blog_authors
language plpgsql
security definer
set search_path = ''
as $$
declare
  author public.blog_authors;
  member public.admin_members;
  base text;
  candidate text;
  n integer := 1;
begin
  if not public.is_admin_member() then
    raise exception 'Not allowed.' using errcode = 'insufficient_privilege';
  end if;
  select * into author from public.blog_authors a where a.member_id = auth.uid();
  if found then
    return author;
  end if;
  select * into member from public.admin_members m where m.user_id = auth.uid();
  base := trim(both '-' from regexp_replace(lower(coalesce(nullif(btrim(member.name), ''), split_part(member.email, '@', 1))), '[^a-z0-9]+', '-', 'g'));
  if base = '' then
    base := 'author';
  end if;
  candidate := left(base, 100);
  while exists (select 1 from public.blog_authors a where a.slug = candidate) loop
    n := n + 1;
    candidate := left(base, 100) || '-' || n;
  end loop;
  insert into public.blog_authors (slug, name, member_id)
  values (candidate, coalesce(nullif(btrim(member.name), ''), split_part(member.email, '@', 1)), auth.uid())
  returning * into author;
  return author;
end
$$;

-- Which posts use which uploaded images: as cover, share image, or an image block in the published or draft doc.
create function public.blog_media_usage()
returns table (media_id uuid, post_id uuid, in_cover boolean, in_content boolean)
language sql
stable
security invoker
set search_path = ''
as $$
  select t.media_id, t.post_id, t.in_cover, t.in_content
  from (
    select
      m.id as media_id,
      p.id as post_id,
      coalesce(p.cover_path = m.path, false) or coalesce(p.og_image_path = m.path, false) as in_cover,
      exists (
        select 1
        from (values (p.content), (p.draft_content)) v (d),
          lateral jsonb_path_query(coalesce(v.d, '{}'::jsonb), 'strict $.**.attrs') a
        where jsonb_typeof(a) = 'object'
          and ((a ->> 'mediaId') = m.id::text
               or ((a ->> 'src') is not null and right(a ->> 'src', length(m.path)) = m.path))
      ) as in_content
    from public.blog_media m
    cross join public.blog_posts p
  ) t
  where t.in_cover or t.in_content
$$;

